import pytest

from bedrock_protocol import v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.ClientToServerHandshake{}
EMPTY = bytes.fromhex("")

GOLDENS = [
    pytest.param(version.ClientToServerHandshakePacket(), EMPTY, id=version.__name__.rpartition(".")[2])
    for version in versions
]


@pytest.mark.parametrize("version", versions)
def test_client_to_server_handshake_is_packet_4(version):
    assert version.packets[4] is version.ClientToServerHandshakePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_to_server_handshake_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_to_server_handshake_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", versions)
def test_client_to_server_handshake_leaves_a_trailing_byte_unread(version):
    with pytest.raises(ValueError, match="trailing bytes"):
        version.ClientToServerHandshakePacket.from_bytes(b"\x01")
